import { MakeLogicType, actions, afterMount, kea, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'

import { buildAiObservabilityStorageConfig } from '../preferenceStorage'

export type AIObservabilityDashboardLogicProps = Record<string, never>

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface aiObservabilityDashboardLogicValues {
    availableDashboards: Array<{
        description: string
        id: number
        name: string
    }>
    availableDashboardsLoading: boolean
    selectedDashboardId: number | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface aiObservabilityDashboardLogicActions {
    loadLLMDashboards: () => {
        value: true
    }
    loadLLMDashboardsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadLLMDashboardsSuccess: (
        availableDashboards: {
            description: string
            id: number
            name: string
        }[],
        payload?: {
            value: true
        }
    ) => {
        availableDashboards: {
            description: string
            id: number
            name: string
        }[]
        payload?: {
            value: true
        }
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface aiObservabilityDashboardLogicMeta {
    __keaTypeGenInternalSelectorTypes: Record<string, never>
}

export type aiObservabilityDashboardLogicType = MakeLogicType<
    aiObservabilityDashboardLogicValues,
    aiObservabilityDashboardLogicActions,
    AIObservabilityDashboardLogicProps,
    aiObservabilityDashboardLogicMeta
>

export const aiObservabilityDashboardLogic = kea<aiObservabilityDashboardLogicType>([
    path(['products', 'ai_observability', 'frontend', 'tabs', 'aiObservabilityDashboardLogic']),
    props({} as AIObservabilityDashboardLogicProps),

    actions({
        loadLLMDashboards: true,
    }),

    reducers(() => ({
        selectedDashboardId: [
            null as number | null,
            buildAiObservabilityStorageConfig('dashboard.selectedDashboardId'),
            {
                loadLLMDashboardsSuccess: (state, { availableDashboards }) => {
                    // If no dashboards available, clear selection
                    if (availableDashboards.length === 0) {
                        return null
                    }

                    // If currently selected dashboard still exists in list, keep it
                    if (state && availableDashboards.some((d) => d.id === state)) {
                        return state
                    }

                    // Otherwise, select first available dashboard (new or after deletion)
                    return availableDashboards[0].id
                },
            },
        ],
    })),

    loaders(() => ({
        availableDashboards: [
            [] as Array<{ id: number; name: string; description: string }>,
            {
                loadLLMDashboards: async () => {
                    const response = await api.dashboards.list({
                        tags: 'llm-analytics',
                        creation_mode: 'unlisted',
                    })
                    const dashboards = response.results || []

                    return dashboards.map((d) => ({
                        id: d.id,
                        name: d.name,
                        description: d.description || '',
                    }))
                },
            },
        ],
    })),

    listeners(({ actions }) => ({
        loadLLMDashboardsSuccess: async ({ availableDashboards }, breakpoint) => {
            if (availableDashboards.length === 0) {
                try {
                    await api.dashboards.createUnlistedDashboard('llm-analytics')
                    await breakpoint(100)
                    actions.loadLLMDashboards()
                } catch (error: unknown) {
                    const err = error as { status?: number }

                    if (err.status === 409) {
                        await breakpoint(100)
                        actions.loadLLMDashboards()
                    } else {
                        console.error('Failed to create default AI observability dashboard:', error)
                    }
                }
            }
        },
    })),

    afterMount(({ actions }) => {
        actions.loadLLMDashboards()
    }),
])
